/* Arrange the controls like the reference instrument's three inset plates. */
(()=>{const instrument=document.querySelector('.instrument'),parameters=document.querySelector('.parameters'),generators=document.querySelector('.generators'),routing=document.querySelector('#advanced');parameters.prepend(generators);instrument.append(routing);const logo=document.querySelector('.motherbox-logo');logo.setAttribute('viewBox','0 0 550 88');logo.innerHTML='<title>MotherBox</title><g fill="#d3ba8c"><text x="275" y="65" text-anchor="middle" font-family="Arial Black,Arial,sans-serif" font-size="67" font-weight="900" letter-spacing="3" textLength="525" lengthAdjust="spacingAndGlyphs">MOTHERBOX</text></g>';})();
document.querySelectorAll('.parameters,#advanced,.bass-editor,.performance-bar,.macros').forEach(el=>{el.classList.add('bolted');const screws=document.createElement('span');screws.className='plate-fasteners';screws.setAttribute('aria-hidden','true');el.append(screws)});
function positionGeneratorScreens(){document.querySelectorAll('#parameters .param').forEach(param=>{const display=param.querySelector('label>.digital-screen');if(display)param.append(display)})}positionGeneratorScreens();new MutationObserver(positionGeneratorScreens).observe(document.querySelector('#parameters'),{childList:true,subtree:true});
colors.splice(0,colors.length,'#a9ed84','#e7bb59','#86db6b','#b2ef86','#e5bd62');
